CREATE TABLE receita_alimentos (
    id          INT PRIMARY KEY AUTO_INCREMENT,
    nome        VARCHAR(255) NOT NULL,
    tipo_macro  ENUM('por_100g', 'total') NOT NULL COMMENT 'por_100g: valores referentes a 100g | total: valores referentes à porção inteira',
    porcao_g    DECIMAL(10,2) NULL        COMMENT 'Obrigatório quando tipo_macro = total. Ex: 1 ovo = 50g',
    energiaKcal DECIMAL(10,2),
    proteina    DECIMAL(10,2),
    lipideos    DECIMAL(10,2),
    carboidrato DECIMAL(10,2),
    fibra       DECIMAL(10,2),
    sodio       DECIMAL(10,2),
    created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    -- garante porcao_g preenchido quando tipo_macro = 'total'
    CONSTRAINT chk_porcao_g CHECK (
        tipo_macro = 'por_100g' OR porcao_g IS NOT NULL
    )
);


-- ============================================================
-- TABELA: receitas
-- ============================================================

CREATE TABLE receitas (
    id           INT PRIMARY KEY AUTO_INCREMENT,
    nome         VARCHAR(255) NOT NULL,
    modo_preparo TEXT,
    porcao_g     DECIMAL(10,2) COMMENT 'Peso de uma porção em gramas',
    rendimento_g DECIMAL(10,2) COMMENT 'Peso total da receita pronta em gramas',
    created_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- ============================================================
-- TABELA: receita_ingredientes
-- Aceita ingredientes de 'alimentos' (IBGE/TACO) ou de
-- 'receita_alimentos' (custom) — nunca os dois ao mesmo tempo
-- ============================================================

CREATE TABLE receita_ingredientes (
    id                  INT PRIMARY KEY AUTO_INCREMENT,
    receita_id          INT           NOT NULL,
    alimento_id         INT           NULL     COMMENT 'FK para alimentos (IBGE/TACO)',
    receita_alimento_id INT           NULL     COMMENT 'FK para receita_alimentos (custom)',
    quantidade_g        DECIMAL(10,2) NOT NULL COMMENT 'Quantidade usada nesta receita em gramas',
    unidade             VARCHAR(50)            COMMENT 'Ex: g, ml, colher, xícara',

    CONSTRAINT fk_ri_receita
        FOREIGN KEY (receita_id)          REFERENCES receitas          (id) ON DELETE CASCADE,
    CONSTRAINT fk_ri_alimento
        FOREIGN KEY (alimento_id)         REFERENCES alimentos         (id) ON DELETE RESTRICT,
    CONSTRAINT fk_ri_receita_alimento
        FOREIGN KEY (receita_alimento_id) REFERENCES receita_alimentos (id) ON DELETE RESTRICT,

    -- um dos dois obrigatoriamente preenchido, nunca os dois
    CONSTRAINT chk_origem CHECK (
        (alimento_id IS NOT NULL AND receita_alimento_id IS NULL) OR
        (alimento_id IS NULL     AND receita_alimento_id IS NOT NULL)
    )
);


-- ============================================================
-- VIEW: vw_receitas_macros
-- Calcula os macros totais e por porção de cada receita
--
-- Lógica de cálculo por origem do ingrediente:
--
-- [alimentos - IBGE/TACO]
--   Valores já estão em por 100g (após UPDATE /100 do script original)
--   kcal = energiaKcal * quantidade_g
--
-- [receita_alimentos - custom, tipo_macro = 'por_100g']
--   Mesmo padrão do IBGE/TACO
--   kcal = energiaKcal * quantidade_g
--
-- [receita_alimentos - custom, tipo_macro = 'total']
--   Usuário informou o valor total para porcao_g gramas
--   Precisa normalizar para a quantidade usada na receita
--   kcal = energiaKcal * (quantidade_g / porcao_g)
-- ============================================================

CREATE OR REPLACE VIEW vw_receitas_macros AS
SELECT
    r.id                                                                AS receita_id,
    r.nome                                                              AS receita,
    r.porcao_g,
    r.rendimento_g,

    -- kcal total da receita
    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL
                THEN a.energiaKcal * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g'
                THEN ra.energiaKcal * i.quantidade_g
            WHEN ra.tipo_macro = 'total'
                THEN ra.energiaKcal * (i.quantidade_g / ra.porcao_g)
        END
    ), 2)                                                               AS kcal_total,

    -- proteína total
    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL
                THEN a.proteina * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g'
                THEN ra.proteina * i.quantidade_g
            WHEN ra.tipo_macro = 'total'
                THEN ra.proteina * (i.quantidade_g / ra.porcao_g)
        END
    ), 2)                                                               AS proteina_total_g,

    -- carboidrato total
    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL
                THEN a.carboidrato * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g'
                THEN ra.carboidrato * i.quantidade_g
            WHEN ra.tipo_macro = 'total'
                THEN ra.carboidrato * (i.quantidade_g / ra.porcao_g)
        END
    ), 2)                                                               AS carboidrato_total_g,

    -- gordura total
    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL
                THEN a.lipideos * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g'
                THEN ra.lipideos * i.quantidade_g
            WHEN ra.tipo_macro = 'total'
                THEN ra.lipideos * (i.quantidade_g / ra.porcao_g)
        END
    ), 2)                                                               AS gordura_total_g,

    -- fibra total
    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL
                THEN a.fibra * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g'
                THEN ra.fibra * i.quantidade_g
            WHEN ra.tipo_macro = 'total'
                THEN ra.fibra * (i.quantidade_g / ra.porcao_g)
        END
    ), 2)                                                               AS fibra_total_g,

    -- sódio total (só disponível em receita_alimentos custom)
    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL
                THEN a.sodio * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g'
                THEN ra.sodio * i.quantidade_g
            WHEN ra.tipo_macro = 'total'
                THEN ra.sodio * (i.quantidade_g / ra.porcao_g)
        END
    ), 2)                                                               AS sodio_total_mg,

    -- ---- macros por porção (proporcional: porcao_g / rendimento_g) ----

    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL  THEN a.energiaKcal * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g' THEN ra.energiaKcal * i.quantidade_g
            WHEN ra.tipo_macro = 'total'    THEN ra.energiaKcal * (i.quantidade_g / ra.porcao_g)
        END
    ) * (r.porcao_g / r.rendimento_g), 2)                              AS kcal_por_porcao,

    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL  THEN a.proteina * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g' THEN ra.proteina * i.quantidade_g
            WHEN ra.tipo_macro = 'total'    THEN ra.proteina * (i.quantidade_g / ra.porcao_g)
        END
    ) * (r.porcao_g / r.rendimento_g), 2)                              AS proteina_por_porcao_g,

    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL  THEN a.carboidrato * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g' THEN ra.carboidrato * i.quantidade_g
            WHEN ra.tipo_macro = 'total'    THEN ra.carboidrato * (i.quantidade_g / ra.porcao_g)
        END
    ) * (r.porcao_g / r.rendimento_g), 2)                              AS carboidrato_por_porcao_g,

    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL  THEN a.lipideos * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g' THEN ra.lipideos * i.quantidade_g
            WHEN ra.tipo_macro = 'total'    THEN ra.lipideos * (i.quantidade_g / ra.porcao_g)
        END
    ) * (r.porcao_g / r.rendimento_g), 2)                              AS gordura_por_porcao_g,

    ROUND(SUM(
        CASE
            WHEN i.alimento_id IS NOT NULL  THEN a.fibra * i.quantidade_g
            WHEN ra.tipo_macro = 'por_100g' THEN ra.fibra * i.quantidade_g
            WHEN ra.tipo_macro = 'total'    THEN ra.fibra * (i.quantidade_g / ra.porcao_g)
        END
    ) * (r.porcao_g / r.rendimento_g), 2)                              AS fibra_por_porcao_g,

    COUNT(i.id)                                                         AS total_ingredientes

FROM receitas r
JOIN receita_ingredientes i  ON i.receita_id          = r.id
LEFT JOIN alimentos       a  ON a.id                  = i.alimento_id
LEFT JOIN receita_alimentos ra ON ra.id               = i.receita_alimento_id
GROUP BY r.id, r.nome, r.porcao_g, r.rendimento_g;


-- ============================================================
-- EXEMPLOS DE USO
-- ============================================================

-- Exemplo 1: ingrediente custom com macros por 100g
-- Usuário sabe que goma de tapioca tem X kcal a cada 100g
VALUES ('Goma de tapioca', 'por_100g', 3.50, 0.002, 0.001, 0.860, 0.001, 0.001);

-- Exemplo 2: ingrediente custom com macros totais
-- Usuário leu no rótulo: "por porção de 30g: 110 kcal, 3g proteína..."
VALUES ('Pasta de amendoim integral', 'total', 30, 110, 3.00, 9.00, 4.00, 1.00, 0.05);

-- Cadastrar a receita Crepioca
VALUES (
    'Crepioca',
    'Misture o ovo com a goma de tapioca até homogeneizar. Leve à frigideira antiaderente em fogo médio e cozinhe dos dois lados.',
    100,   -- 1 unidade (~100g)
    200    -- rendimento total (2 unidades)
);

-- Ingredientes da Crepioca
-- ovo vem da tabela alimentos (IBGE/TACO)
(
    (SELECT id FROM receitas WHERE nome = 'Crepioca'),
    (SELECT id FROM alimentos WHERE nome LIKE '%ovo%inteiro%cru%' LIMIT 1),
    NULL,
    100, 'g'
),
-- goma de tapioca vem de receita_alimentos (custom)
(
    (SELECT id FROM receitas WHERE nome = 'Crepioca'),
    NULL,
    (SELECT id FROM receita_alimentos WHERE nome = 'Goma de tapioca'),
    40, 'g'
);

-- Consultar macros da Crepioca
SELECT * FROM vw_receitas_macros WHERE receita = 'Crepioca';


